//! Differential tests against the pinned reference (TEST-005 §Differential,
//! TASK-018 §8.3): the committed canonical JSON generated by the dev-only
//! Node harness (`tools/reference-layout/`, `bpmn-auto-layout@2.0.0-alpha.2`)
//! is compared with the native engine on element coverage, topology,
//! containment, orthogonal routing and collision freedom. Coordinates may
//! differ; that is explicitly out of contract (EXP-004).

use bpmn_model::BpmnDocument;
use bpmn_model::di::Bounds;

mod common;

struct ReferenceDiagram {
    shapes: Vec<(String, Bounds)>,
    edges: Vec<(String, Vec<(f64, f64)>)>,
}

fn reference_path(stem: &str) -> std::path::PathBuf {
    common::fixtures_dir()
        .join("reference")
        .join(format!("{stem}.json"))
}

fn load_reference(stem: &str) -> ReferenceDiagram {
    let bytes = std::fs::read(reference_path(stem)).unwrap_or_else(|error| {
        panic!(
            "read reference JSON for {stem}: {error} (regenerate with tools/reference-layout/run.mjs; \
             cargo test must not require Node)"
        )
    });
    let value: serde_json::Value = serde_json::from_slice(&bytes).expect("reference JSON parses");
    let pin = &value["reference"];
    assert_eq!(
        pin["commit"].as_str(),
        Some("75a7f30958c7050474d48db09afd4cc7d352ccad"),
        "{stem}: reference JSON was not generated by the pinned commit"
    );
    let mut shapes = Vec::new();
    for shape in value["shapes"].as_array().expect("shapes array") {
        shapes.push((
            shape["bpmnElement"].as_str().expect("id").to_string(),
            Bounds::new(
                shape["x"].as_f64().expect("x"),
                shape["y"].as_f64().expect("y"),
                shape["width"].as_f64().expect("width"),
                shape["height"].as_f64().expect("height"),
            ),
        ));
    }
    let mut edges = Vec::new();
    for edge in value["edges"].as_array().expect("edges array") {
        let waypoints = edge["waypoints"]
            .as_array()
            .expect("waypoints")
            .iter()
            .map(|point| (point[0].as_f64().expect("x"), point[1].as_f64().expect("y")))
            .collect();
        edges.push((
            edge["bpmnElement"].as_str().expect("id").to_string(),
            waypoints,
        ));
    }
    ReferenceDiagram { shapes, edges }
}

/// Checks the shared geometry invariants (orthogonality, docking, interior
/// avoidance, no shape overlap) against an arbitrary shape/edge set, so the
/// reference output is held to the same hard rules as the native one.
fn check_geometry(
    stem: &str,
    side: &str,
    shapes: &[(String, Bounds)],
    edges: &[(String, Vec<(f64, f64)>)],
) {
    let endpoints = |document: &BpmnDocument, flow: &str| {
        let flow = document
            .find_sequence_flow(flow)
            .unwrap_or_else(|| panic!("{stem}: flow {flow} not found"));
        (flow.source_ref.clone(), flow.target_ref.clone())
    };
    let document = common::load_fixture(&format!("core/{stem}.bpmn"));

    // No shape overlap.
    for (index, (id_a, bounds_a)) in shapes.iter().enumerate() {
        for (id_b, bounds_b) in &shapes[index + 1..] {
            let overlap = bounds_a.x < bounds_b.x + bounds_b.width
                && bounds_b.x < bounds_a.x + bounds_a.width
                && bounds_a.y < bounds_b.y + bounds_b.height
                && bounds_b.y < bounds_a.y + bounds_a.height;
            assert!(!overlap, "{stem}/{side}: shapes {id_a} and {id_b} overlap");
        }
    }

    for (flow_id, waypoints) in edges {
        assert!(
            waypoints.len() >= 2,
            "{stem}/{side}: edge {flow_id} has fewer than two waypoints"
        );
        for pair in waypoints.windows(2) {
            let (a, b) = (pair[0], pair[1]);
            assert!(
                a == b || a.0 == b.0 || a.1 == b.1,
                "{stem}/{side}: edge {flow_id} has a diagonal segment"
            );
        }
        let (source_ref, target_ref) = endpoints(&document, flow_id);
        let bounds_of = |id: &str| {
            shapes
                .iter()
                .find(|(element, _)| element == id)
                .map(|(_, bounds)| *bounds)
                .unwrap_or_else(|| panic!("{stem}/{side}: shape {id} missing"))
        };
        let (source, target) = (bounds_of(&source_ref), bounds_of(&target_ref));
        let first = waypoints[0];
        let last = waypoints[waypoints.len() - 1];
        assert!(
            on_boundary(source, first),
            "{stem}/{side}: edge {flow_id} does not dock on source {source_ref}"
        );
        assert!(
            on_boundary(target, last),
            "{stem}/{side}: edge {flow_id} does not dock on target {target_ref}"
        );
        for pair in waypoints.windows(2) {
            for (shape_id, bounds) in shapes {
                if *shape_id == source_ref || *shape_id == target_ref {
                    continue;
                }
                assert!(
                    !segment_hits(bounds, pair[0], pair[1]),
                    "{stem}/{side}: edge {flow_id} enters the interior of {shape_id}"
                );
            }
        }
    }
}

fn on_boundary(bounds: Bounds, point: (f64, f64)) -> bool {
    let (x, y) = point;
    let in_x = x >= bounds.x && x <= bounds.x + bounds.width;
    let in_y = y >= bounds.y && y <= bounds.y + bounds.height;
    (in_x && (y == bounds.y || y == bounds.y + bounds.height))
        || (in_y && (x == bounds.x || x == bounds.x + bounds.width))
}

fn segment_hits(bounds: &Bounds, a: (f64, f64), b: (f64, f64)) -> bool {
    let inset = 1.0;
    let (x, y, w, h) = (
        bounds.x + inset,
        bounds.y + inset,
        bounds.width - 2.0 * inset,
        bounds.height - 2.0 * inset,
    );
    if a.1 == b.1 {
        a.1 > y && a.1 < y + h && a.0.max(b.0) > x && a.0.min(b.0) < x + w
    } else {
        a.0 > x && a.0 < x + w && a.1.max(b.1) > y && a.1.min(b.1) < y + h
    }
}

#[test]
fn native_matches_reference_on_coverage_topology_and_geometry_rules() {
    for (stem, process_id) in common::CORE_FIXTURES {
        let reference = load_reference(stem);
        let outcome = common::layout_core(stem, process_id);

        let native_shapes: Vec<(String, Bounds)> = outcome
            .diagram
            .plane
            .shapes
            .iter()
            .map(|shape| (shape.bpmn_element.clone(), shape.bounds))
            .collect();
        let native_edges: Vec<(String, Vec<(f64, f64)>)> = outcome
            .diagram
            .plane
            .edges
            .iter()
            .map(|edge| {
                (
                    edge.bpmn_element.clone(),
                    edge.waypoints
                        .iter()
                        .map(|point| (point.x, point.y))
                        .collect(),
                )
            })
            .collect();

        // 1. Element coverage: identical shape and edge id sets.
        let mut reference_shape_ids: Vec<&str> =
            reference.shapes.iter().map(|(id, _)| id.as_str()).collect();
        let mut native_shape_ids: Vec<&str> =
            native_shapes.iter().map(|(id, _)| id.as_str()).collect();
        reference_shape_ids.sort_unstable();
        native_shape_ids.sort_unstable();
        assert_eq!(
            reference_shape_ids, native_shape_ids,
            "{stem}: shape coverage differs from the reference"
        );

        let mut reference_edge_ids: Vec<&str> =
            reference.edges.iter().map(|(id, _)| id.as_str()).collect();
        let mut native_edge_ids: Vec<&str> =
            native_edges.iter().map(|(id, _)| id.as_str()).collect();
        reference_edge_ids.sort_unstable();
        native_edge_ids.sort_unstable();
        assert_eq!(
            reference_edge_ids, native_edge_ids,
            "{stem}: edge coverage differs from the reference"
        );

        // 2. Canonical shape sizes agree (events 36, gateways 50, activities 100).
        for (id, reference_bounds) in &reference.shapes {
            let native_bounds = native_shapes
                .iter()
                .find(|(element, _)| element == id)
                .expect("coverage checked")
                .1;
            assert_eq!(
                (reference_bounds.width, reference_bounds.height),
                (native_bounds.width, native_bounds.height),
                "{stem}: canonical size of {id} differs"
            );
        }

        // 3. Both engines satisfy the hard geometry rules on this fixture.
        check_geometry(stem, "reference", &reference.shapes, &reference.edges);
        check_geometry(stem, "native", &native_shapes, &native_edges);
    }
}
